    height_indices = {}
    for i in range(n):
        val = h[i]
        if val not in height_indices:
            height_indices[val] = []
        height_indices[val].append(i)

    ans = 1

    # Iterate over each distinct height
    for indices in height_indices.values():
        m = len(indices)
        if m < 1:
            continue

        # dp[i] will store the length of the longest AP ending at index i in the 'indices' list
        # 'indices' is already sorted by original position
        dp = [1] * m
        # step_map maps (step_size, previous_index) -> length_of_AP_ending_at_previous_index
        # This allows us to efficiently extend an AP.
        step_map = {}

        for i in range(1, m):
            best_l = 1
            # Try all previous indices j < i
            for j in range(i):
                d = indices[i] - indices[j]
                if d > 0:
                    # Check if there's an AP ending at j with step d
                    if (d, indices[j]) in step_map:
                        l = step_map[(d, indices[j])] + 1
                        if l > best_l:
                            best_l = l
            dp[i] = best_l

            # Update step_map for future extensions
            # We need to record that for each j < i, we have an AP of length dp[i] ending at i with step d
            # We iterate j from 0 to i-1 to populate the map for future i's
            for j in range(i):
                d = indices[i] - indices[j]
                if d > 0:
                    step_map[(d, indices[j])] = dp[i]

        current_max = max(dp)
        if current_max > ans:
            ans = current_max

    print(ans)

