import sys
from collections import defaultdict

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        h = []
        for _ in range(n):
            h.append(int(next(iterator)))
    except StopIteration:
        return

    # Group indices by height
    # We store the 1-based indices of buildings for each unique height
    positions_by_height = defaultdict(list)
    for i in range(n):
        positions_by_height[h[i]].append(i + 1)  # Store 1-based indices

    max_count = 1

    # Process each height group independently
    for height_indices in positions_by_height.values():
        m = len(height_indices)
        if m <= 1:
            continue

        # dp[i] will store a dictionary: step -> length
        # dp[i][step] = length of the longest arithmetic subsequence ending at height_indices[i] with step 'step'
        # The indices are sorted in increasing order, so we can iterate and extend.
        dp = [{} for _ in range(m)]

        local_max = 1

        for i in range(m):
            # Try to extend from j < i
            # Since we iterate i from 0 to m-1, when we are at i, all j < i have been processed.
            for j in range(i):
                step = height_indices[i] - height_indices[j]

                # Get length of sequence ending at j with step
                # If step not in dp[j], it means no sequence ending at j with this step exists,
                # so we effectively start a new sequence of length 1 at j.
                prev_len = dp[j].get(step, 1)
                new_len = prev_len + 1

                # Update dp[i]
                if step not in dp[i]:
                    dp[i][step] = new_len
                else:
                    if new_len > dp[i][step]:
                        dp[i][step] = new_len

            # Update local max for this height group
            if not dp[i]:
                # If no extensions found, length is 1 (just the building itself)
                if 1 > local_max:
                    local_max = 1
            else:
                l = max(dp[i].values())
                if l > local_max:
                    local_max = l

        if local_max > max_count:
            max_count = local_max

    print(max_count)

if __name__ == '__main__':
    solve()

class Solution:
    def isBalanced(self, num: str) -> bool:
        # Convert each character to an integer and compute sums for even and odd indices.
        # Note: Python uses 0-based indexing, so "even indices" correspond to index % 2 == 0
        # and "odd indices" correspond to index % 2 == 1.

        even_sum = 0
        odd_sum = 0

        for i, char in enumerate(num):
            digit = int(char)
            if i % 2 == 0:
                even_sum += digit
            else:
                odd_sum += digit

        return even_sum == odd_sum

