class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        for start_idx in range(n):
            if nums[start_idx] != 0:
                continue

            # Try both directions: left (-1) and right (1)
            for direction in [-1, 1]:
                # Create a copy to simulate the process
                arr = list(nums)
                curr = start_idx

                while True:
                    # If out of bounds, stop
                    if curr < 0 or curr >= n:
                        break

                    if arr[curr] == 0:
                        # Move in current direction
                        curr += direction
                    else:
                        # Decrement the value
                        arr[curr] -= 1
                        # Reverse direction
                        direction = -direction
                        # Move in the new direction
                        curr += direction

                # Check if all elements are zero
                if all(x == 0 for x in arr):
                    count += 1

        return count

