class Solution:
    def isZeroArray(self, nums: List[int], queries: List[List[int]]) -> bool:
        n = len(nums)
        # Difference array for range updates
        diff = [0] * (n + 1)

        for l, r in queries:
            diff[l] += 1
            diff[r + 1] -= 1

        # Compute prefix sums to get actual counts
        count = 0
        for i in range(n):
            count += diff[i]
            if count < nums[i]:
                return False

        return True

class Solution:
    def possibleStringCount(self, word: str) -> int:
        count = 1  # Start with 1 for the 0-error case (original = word)

        i = 0
        n = len(word)
        while i < n:
            j = i
            while j < n and word[j] == word[i]:
                j += 1
            length = j - i
            if length > 1:
                count += (length - 1)
            i = j

        return count

