class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # dp[j] will store the maximum points obtainable from the current day to the end (days i to k-1)
        # if we are currently at city j on day i.
        # We initialize dp for the day after the last day (day k) as all zeros.

        dp = [0] * n

        # Process days from k-1 down to 0
        for i in range(k - 1, -1, -1):
            new_dp = []
            for curr in range(n):
                # Option 1: Stay in city curr on day i
                stay_val = stayScore[i][curr] + dp[curr]

                # Option 2: Move to another city on day i
                best_move = -1
                if n > 1:
                    for dest in range(n):
                        if dest != curr:
                            val = travelScore[curr][dest] + dp[dest]
                            if val > best_move:
                                best_move = val

                # Choose the maximum of staying or moving
                if best_move == -1:
                    # This happens when n=1, so no move is possible
                    new_dp.append(stay_val)
                else:
                    new_dp.append(max(stay_val, best_move))

            dp = new_dp

        # The tourist can start at any city on day 0, so take the maximum over all starting cities
        return max(dp)

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        remainder_map = {}
        max_val = float('-inf')

        for i in range(1, n + 1):
            rem = i % k

            if rem == 0:
                if prefix_sum[i] > max_val:
                    max_val = prefix_sum[i]
                remainder_map[0] = min(remainder_map.get(0, float('inf')), prefix_sum[i])
            else:
                if rem in remainder_map:
                    current_sum = prefix_sum[i] - remainder_map[rem]
                    if current_sum > max_val:
                        max_val = current_sum
                    remainder_map[rem] = min(remainder_map[rem], prefix_sum[i])
                else:
                    remainder_map[rem] = prefix_sum[i]

        return max_val

