class Solution:
    def gcd(self, a, b):
        """Compute the greatest common divisor using Euclidean algorithm."""
        while b:
            a, b = b, a % b
        return a

    def lcm(self, a, b):
        """Compute the least common multiple."""
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // self.gcd(a, b)

    def maxLength(self, nums: List[int]) -> int:
        n = len(nums)
        max_len = 0

        # Iterate over all possible starting points of the subarray
        for i in range(n):
            g = nums[i]
            l = nums[i]
            p = nums[i]

            # Extend the subarray from i to j
            for j in range(i, n):
                # Update gcd, lcm, and product as we include nums[j]
                g = self.gcd(g, nums[j])
                l = self.lcm(l, nums[j])
                p *= nums[j]

                # Check the product equivalent condition
                if p == g * l:
                    max_len = max(max_len, j - i + 1)
                else:
                    # Note: Even if the condition fails now, it might become valid 
                    # later if we multiply by 1s or adjust factors. Given the small constraints (n <= 100),
                    # we do not break early to ensure correctness.
                    pass

        return max_len

