class Solution:
    def calculateScore(self, s: str) -> int:
        n = len(s)
        marked = [False] * n
        total_score = 0

        mirror_map = {}
        for c in "abcdefghijklmnopqrstuvwxyz":
            mirror_map[c] = chr(ord('z') - (ord(c) - ord('a')))

        pos_map = {c: [] for c in mirror_map}
        for idx, c in enumerate(s):
            pos_map[c].append(idx)

        for i in range(n):
            target = mirror_map[s[i]]
            positions = pos_map[target]

            # Find the largest index < i in positions
            idx_in_list = bisect.bisect_right(positions, i - 1)
            if idx_in_list == 0:
                continue

            j = positions[idx_in_list - 1]

            # Skip marked indices
            while j > -1 and marked[j]:
                idx_in_list -= 1
                if idx_in_list == 0:
                    break
                j = positions[idx_in_list - 1]

            if j != -1:
                marked[i] = True
                marked[j] = True
                total_score += (i - j)

        return total_score

