class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        star_index = p.index('*')
        prefix = p[:star_index]
        suffix = p[star_index + 1:]

        plen = len(p)
        slen = len(s)

        if plen > slen:
            return False

        for i in range(slen - plen + 1):
            sub = s[i:i+plen]
            if sub.startswith(prefix) and sub.endswith(suffix):
                return True

        return False
